const calm=matchMedia('(prefers-reduced-motion: reduce)');
const cards=[...document.querySelectorAll('.ride-card')];cards.forEach(c=>{['pointerenter','focusin'].forEach(ev=>c.addEventListener(ev,()=>{cards.forEach(x=>x.classList.toggle('active',c===x))}))});
const dialog=document.querySelector('#finder');document.querySelector('#finder-open').onclick=()=>dialog.showModal();document.querySelector('.close-modal').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog&&e.offsetX<0)dialog.close()});
const matches={city:['Make the everyday a good ride.','Comfortable city and lifestyle bikes are a great place to start for commutes, errands and relaxed weekend rides.','bicycles/comfort-lifestyle-pavement/'],trail:['A little dirt. A lot of freedom.','Explore mountain and adventure bikes for unpaved paths and trail days. The team can help match the bike to your terrain.','bicycles/mtb/'],electric:['Go a little further.','Explore electric bikes for assisted riding, longer journeys and a little help on the hills. Ask the shop about fit and range.','bicycles/e-bike/'],kids:['Small wheels. Big adventures.','Find a bike for the next generation of riders. Start with the collection, then ask the shop for sizing advice.','bicycles/kids/']};
document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-match]').forEach(x=>x.classList.toggle('active',x===b));let [title,text,url]=matches[b.dataset.match],r=document.querySelector('#finder-result');r.hidden=false;r.querySelector('h3').textContent=title;r.querySelector('p').textContent=text;r.querySelector('a').href='/'+url;r.querySelector('a').removeAttribute('target')});
const notes=[['Better rides start<br>with a conversation.','Tell us where you ride, what feels good, and what doesn’t. We’ll help you find the right bike, the right upgrade, or simply the right adjustment.'],['A little maintenance.<br>A lot more freedom.','A clean drivetrain, the right tyre pressure, and properly adjusted brakes make a difference. Ask the team what routine care suits your bike and riding.'],['Your neighbourhood.<br>Your kind of bike shop.','Find us in Lakeshore Village, Waterloo. We’re a family-run shop, so you’re always dealing with an owner. Call ahead and let’s talk about your next ride.']];let note=0;function setNote(dir){note=(note+dir+notes.length)%notes.length;document.querySelector('#note-title').innerHTML=notes[note][0];document.querySelector('#note-text').textContent=notes[note][1];document.querySelectorAll('.note-dots i').forEach((x,i)=>x.classList.toggle('active',i===note));if(!calm.matches&&window.gsap)gsap.fromTo('#note-title, #note-text',{y:10,opacity:.3},{y:0,opacity:1,duration:.4,stagger:.05})}document.querySelector('#prev-note').onclick=()=>setNote(-1);document.querySelector('#next-note').onclick=()=>setNote(1);
if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);gsap.matchMedia().add('(prefers-reduced-motion: no-preference)',()=>{gsap.from('.hero h1',{y:50,opacity:0,duration:1.1,ease:'power3.out'});gsap.from('.hero-mark',{rotation:-15,opacity:0,duration:1.4,ease:'power3.out'});gsap.from('.hero-bottom',{y:15,opacity:0,duration:.8,delay:.25});gsap.utils.toArray('.feature-bike,.ride-accordion').forEach(el=>{gsap.fromTo(el,{scale:.92},{scale:1,ease:'none',scrollTrigger:{trigger:el,start:'top 95%',end:'top 30%',scrub:1}});gsap.to(el,{opacity:.3,ease:'none',scrollTrigger:{trigger:el,start:'bottom 15%',end:'bottom top',scrub:1}})});if(innerWidth>700){const rows=gsap.utils.toArray('.service-row');rows.slice(0,-1).forEach((row,i)=>ScrollTrigger.create({trigger:row,start:'top 110px',endTrigger:'.service-stack',end:()=>`bottom ${110+row.offsetHeight}px`,pin:true,pinSpacing:false}));rows.forEach((row,i)=>{row.style.zIndex=i+1})}return()=>ScrollTrigger.getAll().forEach(x=>x.kill())})}
